# Map each position to repeat index
def rep_idx(i):
    if 31<=i<=96: return 0
    if 97<=i<=162: return 1
    if 163<=i<=228: return 2
    if 229<=i<=294: return 3
    if 295<=i<=360: return 4
    return -1

seq=['A']*n
# Give each repeat a distinct pair-type signature so units don't cross-pair.
# Repeat 0: all GC (G...C)
# Repeat 1: all CG (C...G)
# Repeat 2: mix GC interior, AU closers
# Repeat 3: all AU
# Repeat 4: mix CG/AU
# Flanking (rep -1): GC strong
def pairtype(rep, kpos):
    # returns (left,right) complementary bases
    if rep==0:
        return ('G','C')
    elif rep==1:
        return ('C','G')
    elif rep==2:
        if kpos==0: return ('A','U')
        return ('G','C')
    elif rep==3:
        return ('A','U')
    elif rep==4:
        if kpos==0: return ('U','A')
        return ('C','G')
    else:
        return ('G','C')

